def lamp(icon, color, name, tag, means, todo, go, links=""):
    return (f'<div class="lamp {color}"><span class="lamp-ico" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">{LI[icon]}</svg></span>'
            f'<div class="lamp-b"><h3>{E(name)}</h3><span class="lamp-tag">{E(tag)}</span>'
            f'<p><b>Что значит.</b> {means}</p><p><b>Что делать.</b> {todo}</p><p class="lamp-go"><b>Ехать можно?</b> {go}</p>{links}</div></div>')
def lamps(*items): return '<div class="lamps">' + "".join(items) + '</div>'

